@Test
public void test() {
    try {
        for (int i = 0; i < numberOfClients; i++) {
            SimulateLoad simulateLoad = new SimulateLoad(host, port, applicationContext, i);
            simulateLoadList.add(simulateLoad);
            Thread.sleep(100);
        }
        log.error("Clients initialized");
        for (SimulateLoad simulateLoad : simulateLoadList) {
            simulateLoad.start();
            Thread.sleep(50);
        }
        log.error("Clients started");
        boolean running = true;
        while (running) {
            boolean doRunStill = false;
            for (SimulateLoad simulateLoad : simulateLoadList) {
                if (simulateLoad.isTestRunning()) {
                    doRunStill = true;
                    break;
                }
            }
            running = doRunStill;
            try {
                Thread.sleep(200);
            } catch (InterruptedException e) {
                log.error("Error", e);
            }
        }
        double overallTime = 0;
        for (SimulateLoad simulateLoad : simulateLoadList) {
            overallTime += simulateLoad.getAverageTime();
            log.error("Number of calls: " + simulateLoad.getNumberOfCalls() + "overallTime: " + overallTime + " averageTime" + simulateLoad.getAverageTime());
        }
        double deltaAllClients = overallTime / Integer.valueOf(simulateLoadList.size()).doubleValue();
        log.error("Average time per call: " + deltaAllClients);
    } catch (Exception err) {
        log.error("Error", err);
    }
}

